package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(reader, &n, &m)
	a := make([]int, n)
	b := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &a[i])
	}
	for i := 0; i < n; i++ {
		fmt.Fscan(reader, &b[i])
	}

	// Precompute the cost for each position mod n
	// For a regular bracket sequence, we need to choose exactly nm/2 positions as opening brackets
	// and the rest as closing brackets.
	// The key insight is that the minimal cost is achieved by selecting the positions with the
	// smallest (a[i mod n] - b[i mod n]) values as opening brackets.

	// Calculate the total cost if all brackets are closing
	totalCost := 0
	for i := 0; i < n; i++ {
		totalCost += b[i] * (m)
	}

	// Calculate the difference (a[i] - b[i]) for each position mod n
	diff := make([]int, n)
	for i := 0; i < n; i++ {
		diff[i] = a[i] - b[i]
	}

	// We need to select exactly nm/2 positions as opening brackets.
	// Since the sequence is periodic with period n, each residue class mod n appears exactly m times.
	// For each residue class, we can choose how many of its m positions are opening brackets.
	// The total number of opening brackets must be nm/2.

	// To minimize the cost, we should prioritize selecting positions with the smallest (a[i] - b[i]) values.
	// The cost reduction for choosing a position as opening instead of closing is (b[i] - a[i]) = -diff[i].
	// So we want to maximize the sum of (b[i] - a[i]) for the selected positions, which is equivalent to
	// minimizing the sum of diff[i] for the selected positions.

	// Sort the residues by their diff values
	type residue struct {
		diff int
		count int
	}
	residues := make([]residue, n)
	for i := 0; i < n; i++ {
		residues[i] = residue{diff[i], m}
	}

	// Sort residues by diff in ascending order (to pick the smallest diffs first)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if residues[i].diff > residues[j].diff {
				residues[i], residues[j] = residues[j], residues[i]
			}
		}
	}

	// Select the positions with the smallest diffs until we reach nm/2 opening brackets
	remaining := n * m / 2
	for _, r := range residues {
		if remaining <= 0 {
			break
		}
		take := r.count
		if take > remaining {
			take = remaining
		}
		totalCost += take * r.diff
		remaining -= take
	}

	fmt.Println(totalCost)
}
