	}

	nm := n * m
	half := nm / 2

	// dp[i][j] = min cost after i brackets, balance j
	// balance can be up to half
	INF := int64(1 << 60)
	dp := make([][]int64, 2)
	for i := range dp {
		dp[i] = make([]int64, half+1)
		for j := range dp[i] {
			dp[i][j] = INF
		}
	}
	cur := 0
	nxt := 1
	dp[cur][0] = 0

	for i := 0; i < nm; i++ {
		for j := range dp[nxt] {
			dp[nxt][j] = INF
		}
		ai := a[i%n]
		bi := b[i%n]
		for j := 0; j <= half; j++ {
			if dp[cur][j] == INF {
				continue
			}
			// open bracket
			if j+1 <= half {
				if dp[cur][j]+int64(ai) < dp[nxt][j+1] {
					dp[nxt][j+1] = dp[cur][j] + int64(ai)
				}
			}
			// close bracket
			if j > 0 {
				if dp[cur][j]+int64(bi) < dp[nxt][j-1] {
					dp[nxt][j-1] = dp[cur][j] + int64(bi)
				}
			}
		}
