	var n, m int
	fmt.Fscan(r, &n, &m)
	a := make([]int, n)
	b := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(r, &a[i])
	}
	for i := 0; i < n; i++ {
		fmt.Fscan(r, &b[i])
	}

	nm := n * m
	// dp[i][j] = min cost for first i brackets with balance j
	// balance can be up to i, but we cap at nm/2
	maxBal := nm / 2
	const INF = 1 << 60
	dp := make([][]int64, 2)
	for i := 0; i < 2; i++ {
		dp[i] = make([]int64, maxBal+1)
		for j := 0; j <= maxBal; j++ {
			dp[i][j] = INF
		}
	}
	cur := 0
	nxt := 1
	dp[cur][0] = 0

	for i := 0; i < nm; i++ {
		ai := a[i%n]
		bi := b[i%n]
		for j := 0; j <= maxBal; j++ {
			dp[nxt][j] = INF
		}
		for j := 0; j <= maxBal; j++ {
			if dp[cur][j] == INF {
				continue
			}
			// open bracket
			if j+1 <= maxBal {
				if dp[nxt][j+1] > dp[cur][j]+int64(ai) {
					dp[nxt][j+1] = dp[cur][j] + int64(ai)
				}
			}
			// close bracket
			if j > 0 {
				if dp[nxt][j-1] > dp[cur][j]+int64(bi) {
					dp[nxt][j-1] = dp[cur][j] + int64(bi)
				}
			}
		}
		cur, nxt = nxt, cur
	}
	fmt.Println(dp[cur][0])
}
